/** `read` tokens act as a viewer; `write` tokens act as the owner's current role. */
export type ApiTokenScope = "read" | "write";

/**
 * A personal API token as the app presents it. The secret and its hash are
 * never part of this shape: the secret is returned once, from creation, and
 * only the hash is stored.
 */
export interface ApiToken {
  readonly id: string;
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  /** First 12 characters of the secret, for recognising a token in a list. */
  readonly prefix: string;
  readonly expiresAt: IsoTimestamp;
  readonly lastUsedAt: IsoTimestamp | null;
  readonly revokedAt: IsoTimestamp | null;
  readonly createdAt: IsoTimestamp;
}

