/**
 * Personal API token rows. Only the hash of the secret is ever written; every
 * read maps through `toApiToken`, which leaves the hash out of the result.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, count, desc, eq, gt, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { ApiToken } from "@/types/api-token";

export interface InsertApiTokenInput {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
}

export async function insertApiToken(
  input: InsertApiTokenInput,
): Promise<ApiToken> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(apiTokens)
    .values({
      id: newId(),
      orgId: input.orgId,
      userId: input.userId,
      name: input.name,
      scope: input.scope,
      prefix: input.prefix,
      tokenHash: input.tokenHash,
      expiresAt: input.expiresAt,
      lastUsedAt: null,
      revokedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toApiToken(row);
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();

  return row ? toApiToken(row) : null;
}

/** Hash lookup for authentication. The caller passes `hashToken(secret)`. */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();

  return row ? toApiToken(row) : null;
}

/** Every token the user holds in the org, revoked and expired included. */
export async function listApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
      ),
    )
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id))
    .all();

  return rows.map(toApiToken);
}

/** Tokens that are neither revoked nor expired at `now`. */
export async function countUsableApiTokens(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, now),
      ),
    )
    .get();

  return row?.value ?? 0;
}

/** Tokens not yet revoked, expired ones included. Used when a member leaves. */
export async function listUnrevokedApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id))
    .all();

  return rows.map(toApiToken);
}

export async function setApiTokenRevoked(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .returning()
    .get();

  if (!row) throw new Error(`API token ${tokenId} not found in org ${orgId}`);
  return toApiToken(row);
}

export async function touchApiTokenLastUsed(
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken> {
  const row = getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at, updatedAt: at })
    .where(eq(apiTokens.id, tokenId))
    .returning()
    .get();

  if (!row) throw new Error(`API token ${tokenId} not found`);
  return toApiToken(row);
}

