/**
 * Personal API tokens: minting, listing and revoking them, and resolving a presented secret back to an `Actor`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hashToken, randomToken, createApiTokenSchema
 */
import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { createApiTokenSchema } from "@/schemas/api-token";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, apiTokenResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Every secret starts with this, so a leaked one is recognisable in logs. */
const SECRET_PREFIX = "tfk_";
const SECRET_BYTES = 32;
/** Length of the visible prefix stored alongside each token. */
const PREFIX_LENGTH = 12;
const MAX_USABLE_TOKENS_PER_USER = 5;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Mints a token for the actor. The secret is returned here and nowhere else;
 * only its hash is persisted. Invalid input rejects with a `ZodError` before
 * anything is read or written.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  const scope = apiTokenResource(parsed.orgId, actor.userId);
  assertCan(actor, "api_token:create", scope);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", scope);
  }

  const createdAt = new Date();
  const now = toIsoTimestamp(createdAt);

  const usable = await apiTokenRepo.countUsableApiTokens(
    parsed.orgId,
    actor.userId,
    now,
  );
  if (usable >= MAX_USABLE_TOKENS_PER_USER) {
    throw new Error(
      `You can hold at most ${MAX_USABLE_TOKENS_PER_USER} active API tokens per organization`,
    );
  }

  const token = `${SECRET_PREFIX}${randomToken(SECRET_BYTES)}`;
  const expiresAt = toIsoTimestamp(
    new Date(createdAt.getTime() + parsed.expiresInDays * MS_PER_DAY),
  );

  const apiToken = await apiTokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    prefix: token.slice(0, PREFIX_LENGTH),
    tokenHash: hashToken(token),
    createdAt: now,
    expiresAt,
  });

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

