import { beforeAll, describe, expect, it } from "vitest";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as apiTokenService from "@/server/services/api-token-service";
import * as memberService from "@/server/services/member-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";

describe("scratch api tokens", () => {
  let cleanup: () => void;
  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
    registerEventHandlers();
  });

  it("works end to end", async () => {
    const t = await createTenant("tokens");
    const owner = t.actors.owner;
    const member = t.actors.member;
    const viewer = t.actors.viewer;

    const read = await apiTokenService.createApiToken(viewer, {
      orgId: t.org.id, name: "  ci  ", scope: "read", expiresInDays: 7,
    });
    expect(read.token.startsWith("tfk_")).toBe(true);
    expect(read.apiToken.name).toBe("ci");
    expect(read.apiToken.prefix).toBe(read.token.slice(0, 12));
    expect(JSON.stringify(read.apiToken)).not.toContain(read.token);

    await expect(
      apiTokenService.createApiToken(viewer, { orgId: t.org.id, name: "w", scope: "write", expiresInDays: 1 }),
    ).rejects.toThrow();

    const w = await apiTokenService.createApiToken(member, {
      orgId: t.org.id, name: "w", scope: "write", expiresInDays: 1,
