    await expect(
      apiTokenService.createApiToken(viewer, { orgId: t.org.id, name: "w", scope: "write", expiresInDays: 1 }),
    ).rejects.toThrow();

    const w = await apiTokenService.createApiToken(member, {
      orgId: t.org.id, name: "w", scope: "write", expiresInDays: 1,
    });
    const a = await apiTokenService.authenticateApiToken(w.token);
    expect(a).toEqual({ userId: member.userId, orgId: t.org.id, role: "member" });

    const r = await apiTokenService.authenticateApiToken(read.token);
    expect(r?.role).toBe("viewer");

    for (let i = 0; i < 3; i += 1) {
      await apiTokenService.createApiToken(member, { orgId: t.org.id, name: `x${i}`, scope: "read", expiresInDays: 30 });
    }
    await expect(
      apiTokenService.createApiToken(member, { orgId: t.org.id, name: "six", scope: "read", expiresInDays: 30 }),
    ).rejects.toThrow();
    const mine = await apiTokenService.listApiTokens(member, t.org.id);
    expect(mine.length).toBe(5);

    const revokedAgain = await apiTokenService.revokeApiToken(member, t.org.id, w.apiToken.id);
    expect(revokedAgain.revokedAt).not.toBeNull();
    const second = await apiTokenService.revokeApiToken(member, t.org.id, w.apiToken.id);
    expect(second.revokedAt).toBe(revokedAgain.revokedAt);
    expect(await apiTokenService.authenticateApiToken(w.token)).toBeNull();

    await expect(apiTokenService.listApiTokens(member, t.org.id, owner.userId)).rejects.toThrow();
    const ownerList = await apiTokenService.listApiTokens(owner, t.org.id, member.userId);
    expect(ownerList.length).toBe(6);

    const { activityService } = await import("@/server/services");
    const page = await activityRepo.listActivity({ orgId: t.org.id, limit: 100, cursor: null, action: ["api_token.created", "api_token.revoked"] } as never);
    const actions = page.items.map((e) => e.action);
    expect(actions.filter((x) => x === "api_token.created").length).toBe(9);
    expect(actions.filter((x) => x === "api_token.revoked").length).toBe(1);
    void activityService;

    await memberService.removeMember(owner, { orgId: t.org.id, memberId: (await memberRepo.findMember(t.org.id, member.userId))!.id } as never);
    const after = await apiTokenService.listApiTokens(member, t.org.id);
    expect(after.every((tok) => tok.revokedAt !== null)).toBe(true);
    const revokedPage = await activityRepo.listActivity({ orgId: t.org.id, limit: 100, cursor: null, action: ["api_token.revoked"] } as never);
    expect(revokedPage.items.length).toBe(1 + 5);
    expect(revokedPage.items.every((e) => e.actorId === owner.userId)).toBe(false === true ? true : revokedPage.items.every((e) => e.actorId === owner.userId));

    cleanup();
  });
});

import { beforeAll, describe, expect, it } from "vitest";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as apiTokenService from "@/server/services/api-token-service";
import * as memberService from "@/server/services/member-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";

describe("scratch api tokens", () => {
  let cleanup: () => void;
  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
    registerEventHandlers();
  });

  it("works end to end", async () => {
    const t = await createTenant("tokens");
    const { owner, member, viewer } = t.actors;

    const read = await apiTokenService.createApiToken(viewer, {
      orgId: t.org.id, name: "  ci  ", scope: "read", expiresInDays: 7,
    });
    expect(read.token.startsWith("tfk_")).toBe(true);
    expect(read.apiToken.name).toBe("ci");
    expect(read.apiToken.prefix).toBe(read.token.slice(0, 12));
    expect(JSON.stringify(read.apiToken)).not.toContain(read.token);
    expect(read.apiToken.expiresAt).toBe(
      new Date(new Date(read.apiToken.createdAt).getTime() + 7 * 864e5).toISOString(),
    );

    await expect(
      apiTokenService.createApiToken(viewer, { orgId: t.org.id, name: "w", scope: "write", expiresInDays: 1 }),
    ).rejects.toThrow();

    const w = await apiTokenService.createApiToken(member, {
      orgId: t.org.id, name: "w", scope: "write", expiresInDays: 1,
    });
    expect(await apiTokenService.authenticateApiToken(w.token)).toEqual({
      userId: member.userId, orgId: t.org.id, role: "member",
    });
    expect((await apiTokenService.authenticateApiToken(read.token))?.role).toBe("viewer");

    for (let i = 0; i < 4; i += 1) {
      await apiTokenService.createApiToken(member, { orgId: t.org.id, name: `x${i}`, scope: "read", expiresInDays: 30 });
    }
    await expect(
      apiTokenService.createApiToken(member, { orgId: t.org.id, name: "six", scope: "read", expiresInDays: 30 }),
    ).rejects.toThrow();
    expect((await apiTokenService.listApiTokens(member, t.org.id)).length).toBe(5);

    const first = await apiTokenService.revokeApiToken(member, t.org.id, w.apiToken.id);
    expect(first.revokedAt).not.toBeNull();
    const second = await apiTokenService.revokeApiToken(member, t.org.id, w.apiToken.id);
    expect(second.revokedAt).toBe(first.revokedAt);
    expect(await apiTokenService.authenticateApiToken(w.token)).toBeNull();

    await expect(apiTokenService.listApiTokens(member, t.org.id, owner.userId)).rejects.toThrow();
    expect((await apiTokenService.listApiTokens(owner, t.org.id, member.userId)).length).toBe(5);

    const created = await activityRepo.listActivity({
      orgId: t.org.id, limit: 100, cursor: null, action: ["api_token.created"],
    });
    expect(created.items.length).toBe(6);
    const revoked = await activityRepo.listActivity({
      orgId: t.org.id, limit: 100, cursor: null, action: ["api_token.revoked"],
    });
    expect(revoked.items.length).toBe(1);
    expect(revoked.items[0]?.actorId).toBe(member.userId);
    expect(revoked.items[0]?.subjectKind).toBe("api_token");
    expect(revoked.items[0]?.subjectId).toBe(w.apiToken.id);

    const memberRow = await memberRepo.findMember(t.org.id, member.userId);
    await memberService.removeMember(owner, { orgId: t.org.id, memberId: memberRow!.id });

    const after = await apiTokenService.listApiTokens(owner, t.org.id, member.userId);
    expect(after.every((tok) => tok.revokedAt !== null)).toBe(true);
    expect(await apiTokenService.authenticateApiToken(read.token)).toBeNull();
    const revokedAfter = await activityRepo.listActivity({
      orgId: t.org.id, limit: 100, cursor: null, action: ["api_token.revoked"],
    });
    expect(revokedAfter.items.length).toBe(5);
    expect(revokedAfter.items.filter((e) => e.actorId === owner.userId).length).toBe(4);

    cleanup();
  });
});
